        status = SOPC_STATUS_ENCODING_ERROR;
        break;
    case SOPC_DiagnosticInfo_Id:
        val->DiagInfo = SOPC_Malloc(sizeof(SOPC_DiagnosticInfo));
        if (NULL != val->DiagInfo)
        {
            SOPC_DiagnosticInfo_Initialize(val->DiagInfo);
